const languageContext = createContext(null)

export function LanguageProvider({ children }) {
  const [language, setLanguageState] = useState(() => {
    const stored = localStorage.getItem('queueless.language')
    return LANGUAGES.some((item) => item.code === stored) ? stored : 'en'
  })
  const setLanguage = (code) => {
    if (!LANGUAGES.some((item) => item.code === code)) return
    localStorage.setItem('queueless.language', code)
    setLanguageState(code)
  }
  useEffect(() => { document.documentElement.lang = language }, [language])
  const locale = LANGUAGES.find((item) => item.code === language)?.locale || 'en-IN'
  const value = useMemo(() => ({ language, locale, setLanguage }), [language, locale])
  return <languageContext.Provider value={value}>{children}</languageContext.Provider>
}

function translated(value, language) {
  if (typeof value !== 'string' || language === 'en') return value
  const trimmed = value.trim().replace(/\s+/g, ' ')
  const replacement = words[language]?.[trimmed] || clinicWords[language]?.[trimmed] || statusWords[language]?.[trimmed] || screenWords[language]?.[trimmed] || clinicUiWords[language]?.[trimmed]
  if (!replacement) return value
  const start = value.match(/^\s*/)?.[0] || ''
  const end = value.match(/\s*$/)?.[0] || ''
  return `${start}${replacement}${end}`
}

function translateTree(node, language) {
  if (typeof node === 'string') return translated(node, language)
  if (Array.isArray(node)) return Children.map(node, (child) => translateTree(child, language))
  if (!isValidElement(node)) return node
  const props = { ...node.props }
  if (props.children !== undefined) props.children = translateTree(props.children, language)
  for (const attribute of ['placeholder', 'title', 'aria-label', 'alt']) {
    if (typeof props[attribute] === 'string') props[attribute] = translated(props[attribute], language)
  }
  return cloneElement(node, props)
}

export function Localized({ children }) {
  const { language } = useContext(languageContext)
  return <div className={`localized-content lang-${language}`} lang={LANGUAGES.find((item) => item.code === language)?.locale || 'en-IN'}>{translateTree(children, language)}</div>
}

export function LanguageSwitcher() {
  const { language, setLanguage } = useContext(languageContext)
  const [open, setOpen] = useState(false)
  const root = useRef(null)
  const languageNames = { en: 'English', hi: 'हिन्दी', bn: 'বাংলা', ta: 'தமிழ்', te: 'తెలుగు', mr: 'मराठी' }
  const languageDescriptions = { en: 'English · India', hi: 'Hindi · भारत', bn: 'Bengali · ভারত', ta: 'Tamil · இந்தியா', te: 'Telugu · భారతదేశం', mr: 'Marathi · भारत' }
  const scripts = { en: 'Aa', hi: 'अ', bn: 'অ', ta: 'அ', te: 'అ', mr: 'म' }
  const copy = {
    en: ['Choose your language', 'Pick the language you feel most comfortable with.', 'Saved on this device'],
    hi: ['अपनी भाषा चुनें', 'जिस भाषा में आप सहज हों, उसे चुनें।', 'इस डिवाइस पर सेव होगा'],
    bn: ['আপনার ভাষা বেছে নিন', 'যে ভাষায় আপনি স্বচ্ছন্দ, সেটি বেছে নিন।', 'এই ডিভাইসে সংরক্ষিত হবে'],
    ta: ['உங்கள் மொழியைத் தேர்ந்தெடுக்கவும்', 'உங்களுக்கு வசதியான மொழியைத் தேர்ந்தெடுக்கவும்.', 'இந்தச் சாதனத்தில் சேமிக்கப்படும்'],
    te: ['మీ భాషను ఎంచుకోండి', 'మీకు సౌకర్యమైన భాషను ఎంచుకోండి.', 'ఈ పరికరంలో సేవ్ అవుతుంది'],
    mr: ['तुमची भाषा निवडा', 'तुम्हाला सोयीची वाटणारी भाषा निवडा.', 'या डिव्हाइसवर जतन होईल'],
  }[language]
  useEffect(() => {
    if (!open) return undefined
    const closeWhenOutside = (event) => { if (!root.current?.contains(event.target)) setOpen(false) }
    const closeOnEscape = (event) => { if (event.key === 'Escape') setOpen(false) }
    document.addEventListener('pointerdown', closeWhenOutside)
    document.addEventListener('keydown', closeOnEscape)
    return () => { document.removeEventListener('pointerdown', closeWhenOutside); document.removeEventListener('keydown', closeOnEscape) }
  }, [open])
  return <div className="language-switcher" ref={root}>
    <button className="language-trigger" type="button" onClick={() => setOpen(!open)} aria-expanded={open} aria-haspopup="dialog" aria-label={`${copy[0]} · ${languageNames[language]}`}>
      <span className="language-trigger-globe" aria-hidden="true">文</span><span className="language-trigger-copy"><small>LANGUAGE / भाषा</small><strong>{languageNames[language]}</strong></span><span className="language-trigger-chevron" aria-hidden="true">{open ? '−' : '+'}</span>
    </button>
    {open && <section className="language-popover" role="dialog" aria-label={copy[0]}>
      <header className="language-popover-heading"><div><span className="language-overline">QUEUELESS · INDIA</span><h2>{copy[0]}</h2><p>{copy[1]}</p></div><button className="language-close" type="button" onClick={() => setOpen(false)} aria-label="Close language menu">×</button></header>
      <div className="language-options" role="radiogroup" aria-label={copy[0]}>{LANGUAGES.map((item) => <button className={`language-option ${language === item.code ? 'is-selected' : ''}`} key={item.code} type="button" role="radio" aria-checked={language === item.code} onClick={() => { setLanguage(item.code); setOpen(false) }}>
        <span className={`language-script script-${item.code}`}>{scripts[item.code]}</span><span className="language-option-copy"><strong>{languageNames[item.code]}</strong><small>{languageDescriptions[item.code]}</small></span><span className="language-check" aria-hidden="true">{language === item.code ? '✓' : ''}</span>
      </button>)}</div>
      <footer className="language-popover-foot"><span className="privacy-mark">✓</span>{copy[2]}</footer>
    </section>}
  </div>
}

export function useAppLanguage() {
  return useContext(languageContext)
}

export function useTranslate() {
  const { language } = useContext(languageContext)
  return useMemo(() => (value) => translated(value, language), [language])
}
